namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public string ImageEmoji { get; set; } = "🍽️";
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public static class RecipeStore
{
    private static readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious pizza with fresh mozzarella, tomatoes, and basil.",
            ImageEmoji = "🍕",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10–12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
            TotalRatings = 24, RatingSum = 108
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
            ImageEmoji = "🍛",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato puree", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or pan-sear chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato puree, garam masala, and simmer.", "Stir in cream and add chicken.", "Simmer for 15 minutes and serve with rice."],
            TotalRatings = 18, RatingSum = 85
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
            ImageEmoji = "🌮",
            Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells in the oven.", "Fill shells with beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa."],
            TotalRatings = 31, RatingSum = 140
        },
        new()
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Classic Roman pasta with eggs, pecorino cheese, guanciale, and black pepper.",
            ImageEmoji = "🍝",
            Ingredients = ["Spaghetti", "Guanciale (or pancetta)", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
            Steps = ["Cook spaghetti in salted boiling water until al dente.", "Crisp guanciale in a pan over medium heat.", "Whisk eggs with grated pecorino and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with guanciale off heat.", "Add egg mixture quickly, tossing to create a creamy sauce."],
            TotalRatings = 15, RatingSum = 70
        },
        new()
        {
            Id = 5, Title = "Pad Thai", Category = "Thai",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.",
            ImageEmoji = "🍜",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
            Steps = ["Soak rice noodles in warm water for 30 minutes.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the same pan.", "Add noodles, tamarind paste, and fish sauce.", "Toss with shrimp, bean sprouts, and green onions.", "Serve with crushed peanuts and lime wedges."],
            TotalRatings = 22, RatingSum = 97
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh and zesty avocado dip perfect for chips or tacos.",
            ImageEmoji = "🥑",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps = ["Halve and pit avocados, scoop into a bowl.", "Mash to desired consistency.", "Stir in diced onion, tomato, jalapeño, and cilantro.", "Add lime juice and salt to taste.", "Serve immediately with tortilla chips."],
            TotalRatings = 12, RatingSum = 55
        },
        new()
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Description = "Aromatic coconut curry with vegetables and your choice of protein.",
            ImageEmoji = "🥘",
            Ingredients = ["Green curry paste", "Coconut milk", "Chicken or tofu", "Bamboo shoots", "Thai basil", "Bell pepper", "Fish sauce", "Palm sugar"],
            Steps = ["Heat coconut cream in a wok until oil separates.", "Fry curry paste until fragrant.", "Add protein and cook through.", "Pour in coconut milk, add vegetables.", "Season with fish sauce and palm sugar.", "Finish with Thai basil and serve over jasmine rice."],
            TotalRatings = 9, RatingSum = 40
        },
        new()
        {
            Id = 8, Title = "Butter Chicken", Category = "Indian",
            Description = "Rich and creamy tomato-based chicken curry with warm spices.",
            ImageEmoji = "🍗",
            Ingredients = ["Chicken thighs", "Butter", "Tomato sauce", "Heavy cream", "Garam masala", "Cumin", "Garlic", "Ginger", "Kasuri methi"],
            Steps = ["Marinate chicken in yogurt and spices.", "Grill or bake chicken until cooked.", "Melt butter, sauté garlic and ginger.", "Add tomato sauce and spices, simmer 20 minutes.", "Stir in cream and kasuri methi.", "Add chicken and simmer 10 more minutes."],
            TotalRatings = 27, RatingSum = 125
        },
        new()
        {
            Id = 9, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Decadent individual cakes with a molten chocolate center.",
            ImageEmoji = "🍫",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F (220°C).", "Melt chocolate and butter together.", "Whisk eggs with sugar until thick.", "Fold chocolate mixture into eggs.", "Add flour and vanilla, mix gently.", "Pour into greased ramekins, bake 12–14 minutes."],
            TotalRatings = 20, RatingSum = 96
        },
        new()
        {
            Id = 10, Title = "Tiramisu", Category = "Desserts",
            Description = "Classic Italian layered dessert with coffee-soaked ladyfingers and mascarpone cream.",
            ImageEmoji = "🍰",
            Ingredients = ["Ladyfingers", "Mascarpone", "Eggs", "Sugar", "Espresso", "Cocoa powder", "Marsala wine"],
            Steps = ["Brew espresso and let it cool, mix with Marsala.", "Separate eggs; beat yolks with sugar until pale.", "Fold in mascarpone until smooth.", "Whip egg whites to stiff peaks, fold into mascarpone mixture.", "Dip ladyfingers in espresso briefly.", "Layer ladyfingers and cream in a dish, dust with cocoa. Refrigerate 4+ hours."],
            TotalRatings = 16, RatingSum = 75
        }
    ];

    public static IReadOnlyList<Recipe> All => _recipes;

    public static IEnumerable<string> Categories =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c);

    public static IEnumerable<Recipe> ByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public static void Add(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public static void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (_userRating ?? 0) ? "filled" : "") @(star <= _hovered ? "hovered" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => _hovered = star"
                  @onmouseout="() => _hovered = 0"
                  role="button"
                  title="Rate @star star@(star > 1 ? "s" : "")">
                @(star <= (_userRating ?? _hovered) ? "★" : "☆")
            </span>
        }
    </div>
    @if (_userRating.HasValue)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    else
    {
        <span class="rating-prompt">Click to rate</span>
    }
    <span class="rating-avg">
        Avg: @AverageRating.ToString("0.0") (@TotalRatings ratings)
    </span>
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Parameter]
    public double AverageRating { get; set; }

    [Parameter]
    public int TotalRatings { get; set; }

    private int? _userRating;
    private int _hovered;

    private void Rate(int stars)
    {
        if (_userRating.HasValue) return;
        _userRating = stars;
        Models.RecipeStore.AddRating(RecipeId, stars);
        var recipe = Models.RecipeStore.GetById(RecipeId);
        if (recipe is not null)
        {
            AverageRating = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex-wrap: wrap;
    margin: 1rem 0;
}

.stars {
    display: flex;
    gap: 0.15rem;
}

.star {
    font-size: 1.8rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
}

.star:hover {
    transform: scale(1.2);
}

.star.filled {
    color: #f5a623;
}

.star.hovered {
    color: #f5c842;
}

.rating-thanks {
    color: #2e7d32;
    font-weight: 500;
    font-size: 0.9rem;
}

.rating-prompt {
    color: #888;
    font-size: 0.85rem;
}

.rating-avg {
    color: #666;
    font-size: 0.85rem;
}

