@using RecipeShare.Models

<PageTitle>RecipeShare — Home</PageTitle>

<div class="hero">
    <h1>🍳 RecipeShare</h1>
    <p class="lead">Discover, share, and rate recipes from around the world.</p>
    <a href="submit" class="btn btn-primary btn-lg">Submit a Recipe</a>
</div>

<h2 class="mt-4">Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in RecipeStore.Categories)
    {
        <a href="browse/@category" class="category-card">
            <span class="category-emoji">@GetCategoryEmoji(category)</span>
            <span class="category-name">@category</span>
            <span class="category-count">@RecipeStore.ByCategory(category).Count() recipes</span>
        </a>
    }
</div>

<h2 class="mt-4">Popular Recipes</h2>
<div class="recipe-grid">
    @foreach (var recipe in RecipeStore.All.OrderByDescending(r => r.TotalRatings).Take(4))
