@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Components.Shared

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe not found</h1>
    <p><a href="/">← Back to home</a></p>
}
else
{
    <p><a href="browse/@recipe.Category">← Back to @recipe.Category</a></p>

    <div class="recipe-header">
        <span class="detail-emoji">@recipe.ImageEmoji</span>
        <div>
            <h1>@recipe.Title</h1>
            <span class="detail-category">@recipe.Category</span>
        </div>
    </div>

    <p class="detail-desc">@recipe.Description</p>

    <StarRating RecipeId="recipe.Id"
                AverageRating="recipe.AverageRating"
                TotalRatings="recipe.TotalRatings" />

    <div class="detail-sections">
        <section>
            <h2>🥘 Ingredients</h2>
            <ul class="ingredient-list">
                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section>
            <h2>📋 Steps</h2>
            <ol class="step-list">
                @foreach (var step in recipe.Steps)
                {
                    <li>@step</li>
                }
            </ol>
        </section>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

.recipe-header {
    display: flex;
    align-items: center;
    gap: 1.25rem;
    margin-bottom: 1rem;
}

.detail-emoji {
    font-size: 3.5rem;
}

.recipe-header h1 {
    margin-bottom: 0.15rem;
}

.detail-category {
    display: inline-block;
    background: #e8f5e9;
    color: #2e7d32;
    padding: 0.2rem 0.65rem;
    border-radius: 999px;
    font-size: 0.85rem;
    font-weight: 500;
}

.detail-desc {
    font-size: 1.05rem;
    color: #555;
    margin: 0.5rem 0 1rem;
}

.detail-sections {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
    margin-top: 1.5rem;
}

@media (max-width: 768px) {
    .detail-sections {
        grid-template-columns: 1fr;
    }
}

.detail-sections h2 {
    font-size: 1.2rem;
    margin-bottom: 0.75rem;
    padding-bottom: 0.35rem;
    border-bottom: 2px solid #ffe0b2;
}

.ingredient-list {
    list-style: none;
    padding: 0;
}

.ingredient-list li {
    padding: 0.35rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.ingredient-list li::before {
    content: "• ";
    color: #f5a623;
    font-weight: bold;
}

.step-list li {
    margin-bottom: 0.75rem;
    line-height: 1.5;
}

