        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="Model!.IngredientsText" rows="6"
                           placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => Model!.IngredientsText" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="Model!.StepsText" rows="6"
                           placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients and stir." />
            <ValidationMessage For="() => Model!.StepsText" />
        </div>

        <button type="submit" disabled="@_isSubmitting" class="btn btn-primary btn-lg">
            @(_isSubmitting ? "Submitting..." : "Submit Recipe")
        </button>
    </EditForm>
}

@code {
    private RecipeFormModel? Model { get; set; }
    private bool _submitted;
    private bool _isSubmitting;
    private int _newRecipeId;

    protected override void OnInitialized() => Model ??= new();

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        try
        {
            await Task.Delay(300); // simulate processing

            var recipe = new Recipe
            {
                Title = Model!.Title!,
                Category = Model.Category!,
                Description = Model.Description!,
                ImageEmoji = GetEmoji(Model.Category!),
                Ingredients = Model.IngredientsText!
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                    .ToList(),
                Steps = Model.StepsText!
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                    .ToList()
            };

            RecipeStore.Add(recipe);
            _newRecipeId = recipe.Id;
            _submitted = true;
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private static string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        "Desserts" => "🍰",
        _ => "🍽️"
    };

    public class RecipeFormModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3–100 characters.")]
        public string? Title { get; set; }

        [Required(ErrorMessage = "Please select a category.")]
        public string? Category { get; set; }

        [Required(ErrorMessage = "Please add a short description.")]
        [StringLength(300, MinimumLength = 10, ErrorMessage = "Description must be 10–300 characters.")]
        public string? Description { get; set; }

        [Required(ErrorMessage = "Please list at least one ingredient.")]
        [MinLength(3, ErrorMessage = "Please list at least one ingredient.")]
        public string? IngredientsText { get; set; }

        [Required(ErrorMessage = "Please describe at least one step.")]
        [MinLength(3, ErrorMessage = "Please describe at least one step.")]
        public string? StepsText { get; set; }
    }
}

.recipe-form {
    max-width: 640px;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.35rem;
}

.form-group input,
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 1rem;
    font-family: inherit;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #f5a623;
    box-shadow: 0 0 0 3px rgba(245, 166, 35, 0.2);
}

.form-group .validation-message {
    color: #d32f2f;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

.submit-success {
    text-align: center;
    padding: 2rem;
    background: #e8f5e9;
    border-radius: 12px;
    margin-top: 1rem;
}

.submit-success h2 {
    margin-bottom: 0.5rem;
}

.submit-success a {
    display: inline-block;
    margin-top: 1rem;
    font-weight: 600;
}

